```kotlin
class ProfileViewModel(private val repo: UserRepository) : ViewModel() {
    private val _uiState = MutableStateFlow<UiState>(UiState.Loading)
    val uiState: StateFlow<UiState> = _uiState.asStateFlow()

    fun loadUser(id: String) {
        viewModelScope.launch {
            _uiState.value = UiState.Loading
            _uiState.value = try {
                UiState.Success(repo.getUser(id))
            } catch (e: Exception) {
                UiState.Error(e.message)
            }
        }
    }
}

@Composable
fun ProfileScreen(viewModel: ProfileViewModel) {
    val state by viewModel.uiState.collectAsStateWithLifecycle()
    when (state) {
        is UiState.Loading -> LoadingSpinner()
        is UiState.Success -> ProfileContent(state.user)
        is UiState.Error -> ErrorMessage(state.message)
    }
}
```

Note the private mutable backing property (`_uiState`) exposed publicly only as an immutable `StateFlow` — this is a deliberate encapsulation pattern: only the ViewModel itself can push new state; every consumer can only read it. `collectAsStateWithLifecycle()` handles the lifecycle-safety `StateFlow` needs, collecting only while the screen is at least `STARTED`.
